<h1>Vendors</h1><table><tr><th>Company</th><th>Owner</th><th>Email</th><th>Status</th><th>Subscription</th><th>Plan</th><th>Actions</th></tr><?php foreach($vendors as $v): ?><tr><td><?= htmlspecialchars($v['company_name']) ?></td><td><?= htmlspecialchars($v['owner_name']) ?></td><td><?= htmlspecialchars($v['email']) ?></td><td><?= htmlspecialchars($v['verification_status'].'/'.$v['account_status']) ?></td><td><?= htmlspecialchars($v['subscription_status'] ?? 'from_subscription_registry') ?></td><td><?= htmlspecialchars($v['current_plan_key'] ?? $v['plan_key'] ?? '') ?></td><td><form method="post" style="display:inline"><input type="hidden" name="vendor_id" value="<?= htmlspecialchars($v['vendor_id']) ?>"><button class="btn" name="action" value="activate">Activate</button></form> <form method="post" style="display:inline"><input type="hidden" name="vendor_id" value="<?= htmlspecialchars($v['vendor_id']) ?>"><button class="btn secondary" name="action" value="suspend">Suspend</button></form> <form method="post" style="display:inline"><input type="hidden" name="vendor_id" value="<?= htmlspecialchars($v['vendor_id']) ?>"><button class="btn secondary" name="action" value="cancel">Cancel</button></form></td></tr><?php endforeach; ?></table>
